import math
from collections import defaultdict

def is_prime(k):
    if k < 2:
        return False
    for i in range(2, int(math.sqrt(k)) + 1):
        if k % i == 0:
            return False
    return True

def get_prime_factorization(k):
    factors = defaultdict(int)
    d = 2
    temp = k
    while d * d <= temp:
        while temp % d == 0:
            factors[d] += 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] += 1
    return factors

def get_power_info(num):
    """Returns (p, A) if num = p^A and A >= 2. Returns None otherwise."""
    if num <= 3:
        return None

    # Check primes up to sqrt(num) as potential bases
    limit = int(math.sqrt(num)) + 1

    for p in range(2, limit):
        if not is_prime(p):
            continue

        if num % p == 0:
            # Check if num is purely a power of p
            A = 0
            temp = num
            while temp > 1 and temp % p == 0:
                temp //= p
                A += 1

            if temp == 1 and A >= 2:
                return (p, A)

    # Handle the case where num itself is prime (A=1) or prime power base > sqrt(num) (only possible if num is prime)
    # Since we require A >= 2, we only need to check small bases p.
    # If num is prime, A=1, so we skip it.
    return None

def solve_problem():
    M_limit = 20
    N_limit = 20
    solutions = []

    print(f"Starting systematic search for solutions (m, n) up to {M_limit}x{N_limit}...")

    for m in range(1, M_limit + 1):
        for n in range(1, N_limit + 1):
            X = m**2 + n
            Y = m + n**2

            # Get power info for both X and Y
            info_X = get_power_info(X)
            info_Y = get_power_info(Y)

            if info_X is None or info_Y is None:
                continue

            p_X, A = info_X
            p_Y, B = info_Y

            # Check if they share the same prime p
            if p_X == p_Y:
                p = p_X
                # We already ensured A >= 2 and B >= 2 in get_power_info
                solutions.append((m, n, p))
                print(f"Found solution: ({m}, {n}, {p})")

    return solutions

solutions = solve_problem()
print("\n--- Search Results ---")
if solutions:
    total_sum = 0
    for m, n, p in solutions:
        print(f"Triple: ({m}, {n}, {p})")
        total_sum += (m + n + p)
    print(f"Total number of solutions found: {len(solutions)}")
    print(f"Sum of (m+n+p) for all solutions found: {total_sum}")
else:
    print("No solutions found in the searched range.")

def is_prime_power(k):
    if k <= 1:
        return None, None
    for p in range(2, int(k**0.5) + 2):
        if k % p == 0:
            count = 0
            while k % p == 0:
                k //= p
                count += 1
            if k == 1:
                return p, count
            else:
                # Not a prime power
                return None, None
    # k itself is prime
    return k, 1

def check_case_1(n):
    # m = n + 2
    # p^A = (n+1)(n+4)
    # p^B = n^2 + n + 2

    val_A = (n + 1) * (n + 4)
    val_B = n**2 + n + 2

    pA, A = is_prime_power(val_A)
    pB, B = is_prime_power(val_B)

    if pA is not None and pA == pB and A >= 2 and B >= 2:
        return (n + 2, n, pA, A, B)
    return None

def check_case_2(m):
    # n = m + 2
    # p^A = m^2 + m + 2
    # p^B = (m+1)(m+4)

    val_A = m**2 + m + 2
    val_B = (m + 1) * (m + 4)

    pA, A = is_prime_power(val_A)
    pB, B = is_prime_power(val_B)

    if pA is not None and pA == pB and A >= 2 and B >= 2:
        return (m, m + 2, pA, A, B)
    return None

results = []
# Search up to 20 for n in Case 1 (m=n+2)
for n in range(1, 21):
    res = check_case_1(n)
    if res:
        results.append(res)

# Search up to 20 for m in Case 2 (n=m+2)
for m in range(1, 21):
    res = check_case_2(m)
    if res:
        results.append(res)

print("Case 1 (m=n+2) solutions found (m, n, p, A, B):", results)
print("Case 2 (n=m+2) solutions found (m, n, p, A, B):", results)
